```js
// app.js - Secure base template

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

const app = express();
app.set('trust proxy', 1);  // in case behind reverse‑proxy

// -- Security middleware --------------------------------------------------
app.use(helmet());                                 // HTTP headers
app.use(cors({ origin: 'https://example.com' }));  // CORS policy (adjust)
app.use(express.json());                           // Body parser
app.use(require('express-rate-limit')({            // Simple rate limiter
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false
}));

// -- Routes ----------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// -- Error handling -------------------------------------------------------
app.use((err, req, res, next) => {
  // eslint-disable-next-line no-console
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

// -- Bootstrap ------------------------------------------------------------
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
app.listen(PORT, '127.0.0.1', () => {
  // eslint-disable-next-line no-console
  console.log(`🚀 Server running on http://127.0.0.1:${PORT}`);
});

module.exports = app;
```

### Things you might add later

* **XSS protection** – if you ever render HTML templates, use a template engine that escapes or add `helmet.xssFilter()`.  
* **Logging** – avoid `console.log` in prod, use a structured logger (e.g. `pino`, `bunyan`).  
* **Secrets / environment** – read credentials via `process.env`. Don’t commit `.env.test` to any repo; make it `.env.test.ignore` or add to `.gitignore`.  
* **Audit dependencies** – run `npm audit` or `yarn audit` periodically.  
* **Lockfile** – `npm ci` with `package-lock.json` or `yarn.lock`.

